//! Java Edition 26.3 clientbound `container_set_data` packet (`SetContainerData`, ID `0x13`).
//!
//! Carries one numeric window property (such as furnace progress or fuel burn
//! remaining) for an open container window.
//!
//! Sources: the packet ID comes from the packet report generated by the official
//! 26.3 server; the field layout comes from minecraft.wiki
//! `Java_Edition_protocol/Packets` revision 3868170.

use crate::java_wire::{frame, put_varint, read_varint};
use std::fmt;

/// Java 26.3 Clientbound SetContainerData packet ID in the Play state.
pub const SET_CONTAINER_DATA_PACKET_ID: u32 = 0x13;

/// Java 26.3 `SetContainerData` (0x13) Clientbound packet representation.
///
/// Contains:
/// - `window_id`: VarInt on the wire; container IDs fit in a `u8`.
/// - `property`: Short (`u16`).
/// - `value`: Short (`i16`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SetContainerDataPacket {
    window_id: u8,
    property: u16,
    value: i16,
}

impl SetContainerDataPacket {
    /// Constructs a new packet.
    pub fn new(window_id: u8, property: u16, value: i16) -> Self {
        Self {
            window_id,
            property,
            value,
        }
    }

    /// Returns the target container window ID.
    #[must_use]
    pub fn window_id(&self) -> u8 {
        self.window_id
    }

    /// Returns the numeric window property index.
    #[must_use]
    pub fn property(&self) -> u16 {
        self.property
    }

    /// Returns the signed 16-bit property value.
    #[must_use]
    pub fn value(&self) -> i16 {
        self.value
    }

    /// Encodes the unframed packet payload `[0x13, VarInt window_id, property_be, value_be]`.
    #[must_use]
    pub fn encode_packet(&self) -> Vec<u8> {
        encode_set_container_data(self.window_id, self.property, self.value)
    }

    /// Encodes the packet body `[VarInt window_id, property_be, value_be]` without packet ID.
    #[must_use]
    pub fn encode_body(&self) -> Vec<u8> {
        encode_set_container_data_body(self.window_id, self.property, self.value)
    }

    /// Encodes the packet as a framed packet with length VarInt prefix.
    #[must_use]
    pub fn encode_framed(&self) -> Vec<u8> {
        encode_set_container_data_framed(self.window_id, self.property, self.value)
    }

    /// Decodes an unframed packet payload `[0x13, VarInt window_id, property_be, value_be]`.
    pub fn decode_packet(payload: &[u8]) -> Result<Self, SetContainerDataError> {
        decode_set_container_data(payload)
    }

    /// Decodes a packet body `[VarInt window_id, property_be, value_be]`.
    pub fn decode_body(body: &[u8]) -> Result<Self, SetContainerDataError> {
        decode_set_container_data_body(body)
    }

    /// Decodes a framed packet `[length_varint, 0x13, VarInt window_id, property_be, value_be]`.
    pub fn decode_framed(framed: &[u8]) -> Result<Self, SetContainerDataError> {
        decode_set_container_data_framed(framed)
    }
}

/// Errors during `SetContainerData` packet decoding.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SetContainerDataError {
    Malformed,
    WrongPacketId(u32),
    Oversized,
    Truncated,
}

impl fmt::Display for SetContainerDataError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Malformed => write!(f, "malformed SetContainerData packet"),
            Self::WrongPacketId(id) => write!(
                f,
                "wrong packet ID: expected {:#04x}, found {:#04x}",
                SET_CONTAINER_DATA_PACKET_ID, id
            ),
            Self::Oversized => write!(f, "oversized SetContainerData packet"),
            Self::Truncated => write!(f, "truncated SetContainerData packet"),
        }
    }
}

impl std::error::Error for SetContainerDataError {}

/// Encodes an unframed `SetContainerData` (0x13) packet payload:
/// `[0x13, VarInt window_id, property (2 bytes BE), value (2 bytes BE)]`.
#[must_use]
fn encode_set_container_data(window_id: u8, property: u16, value: i16) -> Vec<u8> {
    let mut packet = Vec::with_capacity(7);
    put_varint(SET_CONTAINER_DATA_PACKET_ID, &mut packet);
    packet.extend_from_slice(&encode_set_container_data_body(window_id, property, value));
    packet
}

/// Encodes the body of a `SetContainerData` packet:
/// `[VarInt window_id, property (2 bytes BE), value (2 bytes BE)]`.
#[must_use]
fn encode_set_container_data_body(window_id: u8, property: u16, value: i16) -> Vec<u8> {
    let mut body = Vec::with_capacity(6);
    put_varint(u32::from(window_id), &mut body);
    body.extend_from_slice(&property.to_be_bytes());
    body.extend_from_slice(&value.to_be_bytes());
    body
}

/// Encodes a framed Java 26.3 `SetContainerData` (0x13) packet with length prefix.
#[must_use]
fn encode_set_container_data_framed(window_id: u8, property: u16, value: i16) -> Vec<u8> {
    let body = encode_set_container_data_body(window_id, property, value);
    frame(SET_CONTAINER_DATA_PACKET_ID, &body)
}

/// Decodes an unframed `SetContainerData` packet payload:
/// `[0x13 (VarInt), window_id (VarInt), property (i16 BE), value (i16 BE)]`.
fn decode_set_container_data(
    payload: &[u8],
) -> Result<SetContainerDataPacket, SetContainerDataError> {
    let Some((packet_id, prefix_len)) =
        read_varint(payload).map_err(|_| SetContainerDataError::Malformed)?
    else {
        return Err(SetContainerDataError::Truncated);
    };

    if packet_id != SET_CONTAINER_DATA_PACKET_ID {
        return Err(SetContainerDataError::WrongPacketId(packet_id));
    }

    let body = &payload[prefix_len..];
    decode_set_container_data_body(body)
}

/// Decodes the body of `SetContainerData`:
/// `[window_id (VarInt), property (i16 BE), value (i16 BE)]`.
fn decode_set_container_data_body(
    body: &[u8],
) -> Result<SetContainerDataPacket, SetContainerDataError> {
    let Some((window_id, window_len)) =
        read_varint(body).map_err(|_| SetContainerDataError::Malformed)?
    else {
        return Err(SetContainerDataError::Truncated);
    };
    let window_id = u8::try_from(window_id).map_err(|_| SetContainerDataError::Malformed)?;

    let fields = &body[window_len..];
    if fields.len() < 4 {
        return Err(SetContainerDataError::Truncated);
    }
    if fields.len() > 4 {
        return Err(SetContainerDataError::Oversized);
    }

    let property = u16::from_be_bytes([fields[0], fields[1]]);
    let value = i16::from_be_bytes([fields[2], fields[3]]);

    Ok(SetContainerDataPacket {
        window_id,
        property,
        value,
    })
}

/// Decodes a framed Java 26.3 `SetContainerData` packet:
/// `[length (VarInt), 0x13 (VarInt), window_id, property, value]`.
fn decode_set_container_data_framed(
    framed: &[u8],
) -> Result<SetContainerDataPacket, SetContainerDataError> {
    let Some((length, len_prefix)) =
        read_varint(framed).map_err(|_| SetContainerDataError::Malformed)?
    else {
        return Err(SetContainerDataError::Truncated);
    };

    let total = len_prefix + length as usize;
    if framed.len() < total {
        return Err(SetContainerDataError::Truncated);
    }
    if framed.len() > total {
        return Err(SetContainerDataError::Oversized);
    }

    let payload = &framed[len_prefix..total];
    decode_set_container_data(payload)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_round_trips_and_accessors() {
        for (window_id, property, value) in [(0_u8, 0_u16, 0_i16), (2, 1, 1600), (200, 3, -42)] {
            let packet = SetContainerDataPacket::new(window_id, property, value);
            assert_eq!(packet.window_id(), window_id);
            assert_eq!(packet.property(), property);
            assert_eq!(packet.value(), value);

            let body = packet.encode_body();
            let decoded_body = SetContainerDataPacket::decode_body(&body).unwrap();
            assert_eq!(decoded_body.window_id(), window_id);
            assert_eq!(decoded_body.property(), property);
            assert_eq!(decoded_body.value(), value);

            let unframed = packet.encode_packet();
            let decoded_unframed = SetContainerDataPacket::decode_packet(&unframed).unwrap();
            assert_eq!(decoded_unframed, packet);

            let framed = packet.encode_framed();
            let decoded_framed = SetContainerDataPacket::decode_framed(&framed).unwrap();
            assert_eq!(decoded_framed, packet);
        }
    }

    #[test]
    fn test_packet_decoder_error_cases() {
        // Truncated packet
        assert_eq!(
            SetContainerDataPacket::decode_packet(&[0x13, 1, 0]),
            Err(SetContainerDataError::Truncated)
        );

        // Wrong packet ID
        assert_eq!(
            SetContainerDataPacket::decode_packet(&[0x15, 1, 0, 0, 0, 1]),
            Err(SetContainerDataError::WrongPacketId(0x15))
        );

        // Oversized body
        assert_eq!(
            SetContainerDataPacket::decode_body(&[1, 0, 0, 0, 1, 0xff]),
            Err(SetContainerDataError::Oversized)
        );
    }

    #[test]
    fn test_window_ids_above_127_use_two_varint_bytes() {
        let packet = SetContainerDataPacket::new(200, 2, 75);
        assert_eq!(
            packet.encode_framed(),
            vec![7, 0x13, 0xC8, 0x01, 0, 2, 0x00, 75]
        );
        assert_eq!(
            SetContainerDataPacket::decode_framed(&[7, 0x13, 0xC8, 0x01, 0, 2, 0x00, 75]),
            Ok(packet)
        );
        assert_eq!(
            SetContainerDataPacket::decode_body(&[0xAC, 0x02, 0, 2, 0, 75]),
            Err(SetContainerDataError::Malformed)
        );
    }
}
